### 3.1 Encryption at Rest

**KMS Key Configuration**:

```json
{
    "AtRestEncryptionEnabled": true,
    "KmsKeyId": "arn:aws:kms:us-east-1:ACCOUNT:key/12345678-1234-1234-1234-123456789012",
    "Description": "Fusion Redis cluster encryption key",
    "KeyUsage": "ENCRYPT_DECRYPT",
    "KeySpec": "SYMMETRIC_DEFAULT"
}
```

**Terraform KMS Configuration**:

```hcl
# KMS key for Redis encryption
resource "aws_kms_key" "redis_encryption" {
  description             = "Fusion Redis cluster encryption key"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow Redis Service"
        Effect = "Allow"
        Principal = {
          Service = "elasticache.amazonaws.com"
        }
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey"
        ]
        Resource = "*"
      }
    ]
  })

  tags = {
    Name        = "fusion-redis-encryption-key"
    Environment = var.environment
    Service     = "elasticache"
  }
}

resource "aws_kms_alias" "redis_encryption" {
  name          = "alias/fusion-redis-encryption"
  target_key_id = aws_kms_key.redis_encryption.key_id
}
```

