### 5.2 Application-Level Security

**Secure Redis Wrapper**:

```python
import hashlib
import hmac
import time
from typing import Optional, Dict, Any

class SecureRedisWrapper:
    def __init__(self, redis_client: redis.Redis, encryption_key: str):
        self.redis = redis_client
        self.encryption_key = encryption_key.encode()

    def _encrypt_value(self, value: str) -> str:
        """Encrypt sensitive data before storing."""
        from cryptography.fernet import Fernet
        import base64

        # Use encryption key to create Fernet cipher
        key = base64.urlsafe_b64encode(
            hashlib.sha256(self.encryption_key).digest()
        )
        cipher = Fernet(key)
        encrypted = cipher.encrypt(value.encode())
        return encrypted.decode()

    def _decrypt_value(self, encrypted_value: str) -> str:
        """Decrypt sensitive data after retrieval."""
        from cryptography.fernet import Fernet
        import base64

        key = base64.urlsafe_b64encode(
            hashlib.sha256(self.encryption_key).digest()
        )
        cipher = Fernet(key)
        decrypted = cipher.decrypt(encrypted_value.encode())
        return decrypted.decode()

    def set_secure(self, key: str, value: str, ex: Optional[int] = None) -> bool:
        """Set encrypted value in Redis."""
        encrypted_value = self._encrypt_value(value)
        return self.redis.set(key, encrypted_value, ex=ex)

    def get_secure(self, key: str) -> Optional[str]:
        """Get and decrypt value from Redis."""
        encrypted_value = self.redis.get(key)
        if encrypted_value:
            return self._decrypt_value(encrypted_value)
        return None

    def _create_hmac_signature(self, data: str) -> str:
        """Create HMAC signature for data integrity."""
        return hmac.new(
            self.encryption_key,
            data.encode(),
            hashlib.sha256
        ).hexdigest()

    def set_with_integrity(self, key: str, value: str, ex: Optional[int] = None) -> bool:
        """Set value with integrity check."""
        timestamp = str(int(time.time()))
        data_with_timestamp = f"{value}:{timestamp}"
        signature = self._create_hmac_signature(data_with_timestamp)
        signed_value = f"{data_with_timestamp}:{signature}"
        return self.redis.set(key, signed_value, ex=ex)

    def get_with_integrity(self, key: str, max_age_seconds: int = 3600) -> Optional[str]:
        """Get value with integrity and age verification."""
        signed_value = self.redis.get(key)
        if not signed_value:
            return None

        try:
            value, timestamp, signature = signed_value.rsplit(":", 2)
            data_with_timestamp = f"{value}:{timestamp}"

            # Verify signature
            expected_signature = self._create_hmac_signature(data_with_timestamp)
            if not hmac.compare_digest(signature, expected_signature):
                raise ValueError("Invalid signature")

            # Verify age
            if int(time.time()) - int(timestamp) > max_age_seconds:
                raise ValueError("Data too old")

            return value
        except (ValueError, TypeError) as e:
            # Invalid format or verification failed
            return None
```

