### 6.2 Data Masking

**PII Masking Functions**:

```python
import re
from typing import Dict, Any

class PIIMasker:
    @staticmethod
    def mask_email(email: str) -> str:
        """Mask email address for logging."""
        if "@" not in email:
            return email
        username, domain = email.split("@", 1)
        masked_username = username[:2] + "*" * (len(username) - 2)
        return f"{masked_username}@{domain}"

    @staticmethod
    def mask_phone(phone: str) -> str:
        """Mask phone number for logging."""
        # Remove non-digits
        digits = re.sub(r"\D", "", phone)
        if len(digits) >= 10:
            return f"***-***-{digits[-4:]}"
        return "***-***-****"

    @staticmethod
    def mask_credit_card(card: str) -> str:
        """Mask credit card number."""
        digits = re.sub(r"\D", "", card)
        if len(digits) >= 12:
            return f"****-****-****-{digits[-4:]}"
        return "****-****-****-****"

    @classmethod
    def mask_sensitive_data(cls, data: Dict[str, Any]) -> Dict[str, Any]:
        """Mask all sensitive data in a dictionary."""
        masked_data = data.copy()

        for key, value in masked_data.items():
            if isinstance(value, str):
                if "email" in key.lower():
                    masked_data[key] = cls.mask_email(value)
                elif "phone" in key.lower():
                    masked_data[key] = cls.mask_phone(value)
                elif "card" in key.lower() or "credit" in key.lower():
                    masked_data[key] = cls.mask_credit_card(value)
                elif "password" in key.lower() or "token" in key.lower():
                    masked_data[key] = "****"

        return masked_data
